INSERT INTO harbourstone.commercial_banking.bronze_credit_reviews (review_id, business_id, review_date, risk_grade, probability_of_default_pct, analyst_employee_id, commentary, _source_system, _batch_id) VALUES
  ('CR00001', 'B30001', date_sub(current_date(), 264), 2, 0.10, 'HFG00177', 'Tasman Outfitters continues to trade strongly in retail trade. Revenue of about 168 million is up on last year and debt service cover is comfortable at 2.78x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00002', 'B30001', date_sub(current_date(), 112), 3, 0.25, 'HFG00083', 'Tasman Outfitters continues to trade strongly in retail trade. Revenue of about 168 million is up on last year and debt service cover is comfortable at 2.71x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00003', 'B30002', date_sub(current_date(), 291), 3, 0.25, 'HFG00177', 'Brolga Resources continues to trade strongly in mining services. Revenue of about 7 million is up on last year and debt service cover is comfortable at 2.65x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00004', 'B30002', date_sub(current_date(), 20), 3, 0.25, 'HFG00087', 'Brolga Resources continues to trade strongly in mining services. Revenue of about 7 million is up on last year and debt service cover is comfortable at 2.08x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00005', 'B30003', date_sub(current_date(), 253), 6, 2.00, 'HFG00161', 'Summit Haulage is trading in line with budget, but margins in transport and logistics are under pressure from rising costs. Debt service cover of 1.6x is adequate. Monitor quarterly management accounts.', 'LOANIQ', 'loaniq-0412'),
  ('CR00006', 'B30003', date_sub(current_date(), 81), 7, 5.00, 'HFG00227', 'Summit Haulage reported a second consecutive quarterly loss. The largest customer is about 40 percent of revenue. Debt service cover has fallen to 1.12x, close to covenant. Updated cash flow forecast requested from director Daniel Sharma.', 'LOANIQ', 'loaniq-0412'),
  ('CR00007', 'B30004', date_sub(current_date(), 364), 2, 0.10, 'HFG00226', 'Kestrel Builders continues to trade strongly in construction. Revenue of about 15 million is up on last year and debt service cover is comfortable at 2.12x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00008', 'B30004', date_sub(current_date(), 102), 2, 0.10, 'HFG00165', 'Kestrel Builders continues to trade strongly in construction. Revenue of about 15 million is up on last year and debt service cover is comfortable at 2.42x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00009', 'B30005', date_sub(current_date(), 418), 2, 0.10, 'HFG00087', 'Tasman Constructions continues to trade strongly in construction. Revenue of about 29 million is up on last year and debt service cover is comfortable at 2.69x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
  ('CR00010', 'B30005', date_sub(current_date(), 93), 2, 0.10, 'HFG00119', 'Tasman Constructions continues to trade strongly in construction. Revenue of about 29 million is up on last year and debt service cover is comfortable at 3.07x. No concerns; grade maintained.', 'LOANIQ', 'loaniq-0412'),
